use std::env;
use std::process::exit;

struct Parser {
    args: Vec<String>,
    pos_args: Vec<String>,
    flags: Vec<String>,
    params: std::collections::HashMap<String, String>,
}

impl Parser {
    fn new() -> Self {
        Self {
            args: Vec::new(),
            pos_args: Vec::new(),
            flags: Vec::new(),
            params: std::collections::HashMap::new(),
        }
    }

    fn parse(&mut self, args: Vec<String>) {
        self.args = args;
        let mut iter = self.args.iter().skip(1).peekable();
        while let Some(arg) = iter.next() {
            if arg.starts_with('-') {
                if let Some(next_arg) = iter.peek() {
                    if next_arg.starts_with('-') {
                        self.flags.push(arg.clone());
                    } else {
                        self.params.insert(arg.clone(), next_arg.to_string());
                        iter.next();
                    }
                } else {
                    self.flags.push(arg.clone());
                }
            } else {
                self.pos_args.push(arg.clone());
            }
        }
    }

    fn is_flag_set(&self, flag: &str) -> bool {
        self.flags.contains(&flag.to_string())
    }

    fn pos_args(&self) -> &Vec<String> {
        &self.pos_args
    }

    fn flags(&self) -> &Vec<String> {
        &self.flags
    }

    fn params(&self) -> &std::collections::HashMap<String, String> {
        &self.params
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut cmdl = Parser::new();
    cmdl.parse(args);

    if cmdl.is_flag_set("-v") {
        println!("Verbose, I am.");
    }

    println!("Positional args:");
    for pos_arg in cmdl.pos_args() {
        println!("\t{}", pos_arg);
    }

    println!("\nFlags:");
    for flag in cmdl.flags() {
        println!("\t{}", flag);
    }

    println!("\nParameters:");
    for (key, value) in cmdl.params() {
        println!("\t{} : {}", key, value);
    }

    exit(0);
}

use std::env;
use std::process::exit;
use std::collections::HashMap;

struct Parser {
    // simulate the internal argh state
    flags: Vec<String>,
    params: HashMap<String, String>,
    pos_args: Vec<String>,
}

impl Parser {
    fn new() -> Self {
        Self {
            flags: Vec::new(),
            params: HashMap::new(),
            pos_args: Vec::new(),
        }
    }

    fn parse(&mut self, args: Vec<String>) {
        let mut iter = args.into_iter();
        iter.next(); // skip the executable name
        while let Some(arg) = iter.next() {
            if arg.starts_with('-') {
                if let Some(next_arg) = iter.next() {
                    if !next_arg.starts_with('-') {
                        self.params.insert(arg, next_arg);
                    } else {
                        self.flags.push(arg);
                        self.pos_args.push(next_arg);
                    }
                } else {
                    self.flags.push(arg);
                }
            } else {
                self.pos_args.push(arg);
            }
        }
    }

    fn has_flag(&self, flag: &str) -> bool {
        self.flags.iter().any(|f| f == flag)
    }

    fn pos_args(&self) -> &[String] {
        &self.pos_args
    }

    fn flags(&self) -> impl Iterator<Item = &String> {
        self.flags.iter()
    }

    fn params(&self) -> impl Iterator<Item = (&String, &String)> {
        self.params.iter()
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut cmdl = Parser::new();
    cmdl.parse(args);

    if cmdl.has_flag("-v") {
        println!("Verbose, I am.");
    }

    println!("Positional args:");
    for pos_arg in cmdl.pos_args() {
        println!("\t{}", pos_arg);
    }

    println!("\nFlags:");
    for flag in cmdl.flags() {
        println!("\t{}", flag);
    }

    println!("\nParameters:");
    for (key, value) in cmdl.params() {
        println!("\t{} : {}", key, value);
    }

    exit(0);
}

use std::env;

struct Argh {
    // In an actual translation, this would be more complex to handle various functionalities.
    positional_args: Vec<String>,
    flags: Vec<String>,
    params: Vec<(String, String)>,
    verbose: bool,
}

impl Argh {
    fn new(args: Vec<String>) -> Self {
        let mut positional_args = Vec::new();
        let mut flags = Vec::new();
        let mut params = Vec::new();
        let mut verbose = false;

        let mut args_iter = args.iter();
        while let Some(arg) = args_iter.next() {
            match arg.as_str() {
                "-v" => verbose = true,
                _ if arg.starts_with('-') => flags.push(arg.clone()),
                _ => positional_args.push(arg.clone()),
            }
        }

        Argh {
            positional_args,
            flags,
            params,
            verbose,
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let cmdl = Argh::new(args);

    if cmdl.verbose {
